import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Parlaklık, pozlama ve kontrast; üçü de fotoğrafı aydınlatır ama farklı çalışır. Birini bilmek, diğerini bilmek demek değildir.</p>\n<p>Yanlış kontrol, fotoğrafı bozar. Parlaklık gereken yerde kontrast artırmak, görseli sertleştirir.</p>\n<p>Bu yazı, her kontrolün ne yaptığını, nasıl etkileştiğini ve hangi durumda hangisini kullanacağınızı anlatıyor.</p>\n<h2 id=\"what-each-does\">Her kontrol ne yapar?</h2>\n<p>Parlaklık, tüm pikselleri birlikte aydınlatır ya da karartır. Genel aydınlık seviyesini kaydırır.</p>\n<p>Pozlama, çekim sırasındaki ışık miktarıdır. Düzenlemede pozlama, parlak alanları koruyarak gölgeleri açar.</p>\n<p>Kontrast, açık ve koyu arasındaki farkı artırır ya da azaltır. Derinlik ve canlılık verir.</p>\n<h2 id=\"brightness-explained\">Parlaklık, basitçe açıklanıyor</h2>\n<p>Parlaklık, fotoğrafın genel aydınlığıdır. Kaydırıcıyı sağa çekmek fotoğrafı açar; sola çekmek koyulaştırır.</p>\n<p>Parlaklık, tüm tonları eşit kaydırır. Koyu ve açık alanlar birlikte değişir.</p>\n<p>Parlaklık, hızlı düzeltmeler için idealdir. Koyu fotoğrafı açmak, tek kaydırıcıyla olur.</p>\n<h2 id=\"exposure-explained\">Pozlama, basitçe açıklanıyor</h2>\n<p>Pozlama, sensöre düşen ışık miktarıdır. Çekim sırasında ayarlanır; sonradan tam düzeltilemez.</p>\n<p>Düzenlemede pozlama düzeltmesi, parlak alanları korur. Gökyüzü beyazlamadan gölgeler açılır.</p>\n<p>Pozlama, parlaklıktan daha akıllıdır. Tonları ayrı ayrı işler.</p>\n<h2 id=\"contrast-explained\">Kontrast, basitçe açıklanıyor</h2>\n<p>Kontrast, açık ve koyu arasındaki farktır. Yüksek kontrast, fotoğrafı canlı gösterir.</p>\n<p>Düşük kontrast, fotoğrafı düz gösterir. Sisli fotoğraflar düşük kontrastlıdır.</p>\n<p>Kontrast, renkleri de etkiler. Kontrast artınca renkler doygun görünür.</p>\n<h2 id=\"how-they-interact\">Üç kontrol nasıl etkileşir?</h2>\n<p>Parlaklık açar, kontrast derinlik verir. Birlikte kullanıldıklarında fotoğraf canlanır.</p>\n<p>Pozlama, parlaklığın akıllı sürümüdür. Gölgeleri açar, parlak alanları korur.</p>\n<p>Üçünü birlikte abartmak, fotoğrafı yapay gösterir. Her birini küçük adımlarla ayarlayın.</p>\n<h2 id=\"when-to-use-brightness\">Parlaklık ne zaman kullanılmalı?</h2>\n<p>Fotoğraf genel olarak koyuysa parlaklık kullanın. Tek kaydırıcıyla düzelir.</p>\n<p>Belge ve ekran görüntülerinde parlaklık kullanın. Yazılar okunur hâle gelir.</p>\n<p>Hızlı düzeltmelerde parlaklık kullanın. Zaman yoksa tek kontrol yeterlidir.</p>\n<h2 id=\"when-to-use-exposure\">Pozlama ne zaman kullanılmalı?</h2>\n<p>Gökyüzü parlak, ön plan koyuysa pozlama kullanın. Parlaklık, gökyüzünü beyazlatır; pozlama korumaz.</p>\n<p>Fotoğraf makinesinde çekim sırasında pozlamayı ayarlayın. Sonradan düzeltme, çekim kadar iyi olmaz.</p>\n<p>Portrelerde pozlama kullanın. Yüz açılır, arka plan korunur.</p>\n<h2 id=\"when-to-use-contrast\">Kontrast ne zaman kullanılmalı?</h2>\n<p>Fotoğraf düz görünüyorsa kontrast kullanın. Sisli ve soluk fotoğraflar kontrastla canlanır.</p>\n<p>Metin için kontrast kullanın. Yazı, zeminden ayrılmalıdır.</p>\n<p>Siyah beyaz fotoğraflarda kontrast kullanın. Kontrast, siyah beyazın ruhudur.</p>\n<h2 id=\"order-of-edits\">Doğru sıra: önce parlaklık, sonra kontrast</h2>\n<p>Önce parlaklığı ayarlayın. Genel aydınlık doğru olmalıdır.</p>\n<p>Sonra kontrastı ayarlayın. Derinlik ve canlılık ekleyin.</p>\n<p>Sıralama önemlidir. Önce kontrast artırmak, koyu alanları daha da karartır.</p>\n<h2 id=\"portraits\">Portreler: hangi kontrol daha önemli?</h2>\n<p>Portrelerde parlaklık önemlidir. Yüz, fotoğrafın en önemli parçasıdır; karanlık kalmamalıdır.</p>\n<p>Kontrastı düşük tutun. Fazla kontrast, cildi sert gösterir.</p>\n<p>Pozlama, portrelerde idealdir. Yüz açılır, arka plan korunur.</p>\n<h2 id=\"landscapes\">Manzaralar: gökyüzü ve ön plan dengesi</h2>\n<p>Manzaralarda gökyüzü parlak, ön plan koyu olur. Parlaklık, gökyüzünü beyazlatır.</p>\n<p>Pozlama düzeltmesi kullanın. Ön plan açılır, gökyüzü korunur.</p>\n<p>Kontrastı orta tutun. Fazla kontrast, manzarayı yapay gösterir.</p>\n<h2 id=\"screenshots\">Ekran görüntüleri ve belgeler: önce parlaklık</h2>\n<p>Ekran görüntülerinde parlaklık kullanın. Yazılar okunur hâle gelir.</p>\n<p>Kontrastı sonra ekleyin. Yazılar, zeminden ayrılmalıdır.</p>\n<p>Belgelerde +15 ile +25 parlaklık kullanın. Kâğıt beyazı açılmalı, yazı koyu kalmalıdır.</p>\n<h2 id=\"text-over-photos\">Fotoğrafların üzerindeki metin: kontrast anahtardır</h2>\n<p>Metin için kontrast anahtardır. Yazı ile zemin arasındaki fark büyük olmalıdır.</p>\n<p>Fotoğrafı koyulaştırın ya da açın. Beyaz yazı koyu zeminde, siyah yazı açık zeminde okunur.</p>\n<p>Panel kullanın. Yarı saydam koyu panel, metni her zeminde okunur yapar.</p>\n<h2 id=\"common-confusions\">Üçü arasındaki yaygın karışıklıklar</h2>\n<p>Karışıklık: parlaklık ve pozlama aynıdır. Gerçek: pozlama, parlak alanları koruyarak çalışır.</p>\n<p>Karışıklık: kontrast koyu fotoğrafı düzeltir. Gerçek: kontrast, koyu alanları daha da karartır.</p>\n<p>Karışıklık: üçü birlikte artırılmalıdır. Gerçek: her biri ayrı ayrı, küçük adımlarla ayarlanır.</p>\n<h2 id=\"testing-combinations\">Onaylamadan önce kombinasyonları test etmek</h2>\n<p>Karşılaştırma modunu kullanın. Orijinali ve düzenlenen sürümü yan yana görün.</p>\n<p>Bir kontrolü değiştirip sonucu izleyin. Sonra diğerini ayarlayın.</p>\n<p>Şüphede kalırsanız az ayarlayın. Hafif düzeltme, aşırı düzeltmeden her zaman iyidir.</p>\n<h2 id=\"cheat-sheet\">Hızlı karar kılavuzu</h2>\n<p>Koyu fotoğraf: parlaklık +10 ile +20. Düz fotoğraf: kontrast +10 ile +20.</p>\n<p>Gökyüzü parlak, ön plan koyu: pozlama düzeltmesi. Metin: kontrast artırın.</p>\n<p>Bu listeyi kaydedin. Her düzenlemede yeniden düşünmek zaman kaybıdır.</p>\n<h2 id=\"three-controls-for-thumbnails\">Küçük resimler için parlaklık, pozlama ve kontrast</h2>\n<p>Küçük resimlerde kontrast önemlidir. Küçük ekranda düz fotoğraf kaybolur.</p>\n<p>Parlaklığı +10 tutun. Küçük resim, akışta parlak görünmelidir.</p>\n<p>Metin ekleyecekseniz kontrastı artırın. Yazı, küçük ekranda okunmalıdır.</p>\n<p>Özetle: önce parlaklık, sonra kontrast; pozlama çekimde ayarlanır. Adımlar için <a href=\"/tr/blog/gorsel-parlakligi-nasil-ayarlanir\">Görsel parlaklığı nasıl ayarlanır</a> ve <a href=\"/tr/blog/gorsel-kontrasti-nasil-ayarlanir\">görsel kontrastı nasıl ayarlanır</a> yazılarına bakın. Metin için <a href=\"/tr/blog/kontrast-okunabilirlik-fotograf-uzerinde-metin\">kontrast ve okunabilirlik</a> yazısı yardımcı olur. Araçlar: <a href=\"/tr/gorsel-parlaklik-ayarla\">parlaklık düzenleyici</a> ve <a href=\"/tr/gorsel-kontrast-ayarla\">kontrast düzenleyici</a> sayfalarındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Parlaklık ile kontrast arasındaki fark nedir?","answer":"Parlaklık tüm pikselleri birlikte aydınlatır ya da karartır; genel aydınlık seviyesini kaydırır. Kontrast, açık ve koyu arasındaki farkı artırır ya da azaltır; derinlik verir. Koyu fotoğrafta parlaklık, düz fotoğrafta kontrast kullanılır."},{"question":"Pozlama parlaklıkla aynı şey mi?","answer":"Hayır. Pozlama, çekim sırasındaki ışık miktarıdır; düzenlemede pozlama düzeltmesi parlak alanları koruyarak gölgeleri açar. Parlaklık ise tüm tonları eşit kaydırır; gökyüzünü beyazlatabilir. Pozlama daha akıllıdır."},{"question":"Parlaklığı mı kontrastı mı önce ayarlamalıyım?","answer":"Önce parlaklığı ayarlayın, sonra kontrastı. Parlaklık genel aydınlığı düzeltir; kontrast derinlik verir. Önce kontrast artırmak, koyu alanları daha da karartır. Sıralama, doğru dengeyi bulmanızı sağlar."},{"question":"Fotoğrafım aydınlattıktan sonra neden düz görünüyor?","answer":"Çünkü parlaklık kontrastı düşürür; renkler solar ve derinlik kaybolur. Biraz kontrast ekleyin; +10 ile +20 arası genellikle yeterlidir. Önce parlaklığı, sonra kontrastı ayarlayın."},{"question":"Kontrast çok koyu bir fotoğrafı düzeltebilir mi?","answer":"Hayır. Kontrast, koyu alanları daha da karartır; koyu fotoğrafı düzeltmez. Önce parlaklıkla açın, sonra kontrast ekleyin. Çok koyu fotoğrafta kaybolan ayrıntı geri gelmez."},{"question":"Sisli bir manzara fotoğrafı için hangi kontrolü kullanmalıyım?","answer":"Kontrast kullanın; +10 ile +20 arası sisli fotoğrafı canlandırır. Parlaklık da ekleyebilirsiniz ama önce kontrastı deneyin. Gökyüzünü beyazlatmamak için parlaklığı düşük tutun."}];
